def gen(rng):
    def fmt(a, k):
        return f"{len(a)} {k}\n" + ' '.join(map(str, a))
    tests = [
        fmt([5], 1), fmt([-5], 1), fmt([0], 1), fmt([1, 2, 3], 3), fmt([-1, -2, -3], 2),
        fmt([4, -2, 5, 6, -9, 3, 8], 3), fmt([0, 0, -1, 0, 0], 2), fmt([3, 0, -5, -6], 4),
    ]
    for n in range(2, 16):
        for _ in range(2):
            k = rng.randint(1, n)
            neg = rng.choice([0.1, 0.4, 0.8])
            a = [(-rng.randint(1, 9) if rng.random() < neg else rng.randint(0, 9)) for _ in range(n)]
            tests.append(fmt(a, k))
    n = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)], 50000))
    tests.append(fmt([rng.randint(0, 10**9) for _ in range(n - 1)] + [-1], 50000))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)], 1))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)], n))
    tests.append(fmt([(-7 if i % 40000 == 39999 else rng.randint(0, 100)) for i in range(n)], 30000))
    return tests

